function buildWhatsAppInteractive(input, phone) {
  const mensaje = input;

  const optionRegex = /\d+\)\s*([^\n]+)/g;
  const options = [];
  let match;

  while ((match = optionRegex.exec(mensaje)) !== null) {
    options.push(match[1].trim());
  }

  const bodyText = mensaje.split(/\d+\)/)[0].trim();

  // 🔘 BUTTONS
  if (options.length === 2) {
    return {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to: phone,
      type: "interactive",
      interactive: {
        type: "button",
        body: { text: bodyText },
        action: {
          buttons: options.map((opt) => ({
            type: "reply",
            reply: { id: opt, title: opt },
          })),
        },
      },
    };
  }

  // 📋 LIST
  if (options.length >= 3) {
    return {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to: phone,
      type: "interactive",
      interactive: {
        type: "list",
        header: {
          type: "text",
          text: "Seleccione una opción",
        },
        body: { text: bodyText },
        action: {
          button: "Ver opciones",
          sections: [
            {
              title: "Opciones disponibles",
              rows: options.map((opt, index) => ({
                id: `opt_${index + 1}`,
                // Corta el texto a 24 caracteres si es más largo
                title: opt.toString().substring(0, 24),
                // Si necesitas pasar una descripción dinámica, harías lo mismo:
                description: "".substring(0, 24),
              })),
            },
          ],
        },
      },
    };
  }

  // ❌ NO INTERACTIVO
  return false;
}

// =======================
// 🚀 EJECUCIÓN EN N8N
// =======================

const mensaje = $input.first().json.output.mensaje;
const phone = $("WhatsApp Trigger").first().json.messages[0].from;

const result = buildWhatsAppInteractive(mensaje, phone);

// ✅ SI ES INTERACTIVO
if (result) {
  return [
    {
      json: {
        isInteractive: true,
        mensaje: result,
      },
    },
  ];
}

// ❌ SI NO ES INTERACTIVO
return [
  {
    json: {
      isInteractive: false,
      mensaje: mensaje,
    },
  },
];

